/* Yellow Panther 46 by gagan-gv — https://uiverse.io/gagan-gv/yellow-panther-46 */
.loader {
  width: 12em;
  height: 1em;
  border-radius: 8px;
  background-color: #47a7ff44;
}

.loader div {
  height: 100%;
  width: 100%;
  border-radius: 8px;
  background-color: #47a7ff;
  animation: width7435 5s linear infinite;
  transition: all;
}

@keyframes width7435 {
  from {

    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}
